# Postępowanie karne (Kodeks postępowania karnego).
SEG = "KPK"
CAT = "plapKarProc"
Q = [
    ("Do kiedy oskarżonego uważa się za niewinnego?",
     "Do prawomocnego stwierdzenia winy", ["Do przedstawienia mu zarzutów", "Do wniesienia aktu oskarżenia", "Do ogłoszenia wyroku I instancji"],
     "Art. 5 § 1 KPK: oskarżonego uważa się za niewinnego, dopóki wina nie zostanie udowodniona i stwierdzona prawomocnym wyrokiem."),
    ("Jak rozstrzyga się w procesie karnym wątpliwości, których nie da się usunąć?",
     "Na korzyść oskarżonego", ["Według uznania sądu", "Na korzyść pokrzywdzonego", "Przez powołanie biegłego"],
     "Art. 5 § 2 KPK (in dubio pro reo): niedające się usunąć wątpliwości rozstrzyga się na korzyść oskarżonego."),
    ("Czy oskarżony musi dowodzić swojej niewinności?",
     "Nie ma takiego obowiązku", ["Tylko w sprawach o zbrodnie", "Tylko na wezwanie sądu", "Tylko w trybie przyspieszonym"],
     "Art. 74 § 1 KPK: oskarżony nie ma obowiązku dowodzenia niewinności ani dostarczania dowodów na swoją niekorzyść. Musi jednak poddać się niektórym badaniom, np. oględzinom zewnętrznym ciała (§ 2)."),
    ("Jak nazywa się zasada nakazująca wszcząć i przeprowadzić postępowanie o czyn ścigany z urzędu?",
     "Legalizmu", ["Oportunizmu", "Skargowości", "Prawdy materialnej"],
     "Art. 10 § 1 KPK wyraża zasadę legalizmu: organ powołany do ścigania musi wszcząć i przeprowadzić postępowanie, a oskarżyciel publiczny wnieść i popierać oskarżenie o czyn ścigany z urzędu."),
    ("Co robi organ z postępowaniem, gdy nastąpiło przedawnienie karalności czynu?",
     "Umarza je", ["Zawiesza je", "Przekazuje je sądowi", "Kończy wyrokiem uniewinniającym"],
     "Art. 17 § 1 pkt 6 KPK: nie wszczyna się postępowania, a wszczęte umarza, gdy nastąpiło przedawnienie karalności."),
    ("Który sąd orzeka w pierwszej instancji w sprawach o zbrodnie?",
     "Okręgowy", ["Rejonowy", "Apelacyjny", "Wojewódzki"],
     "Art. 25 § 1 pkt 1 KPK: sąd okręgowy orzeka w pierwszej instancji w sprawach o zbrodnie określone w Kodeksie karnym i w ustawach szczególnych."),
    ("W którym wypadku oskarżony musi mieć obrońcę?",
     "Gdy nie ukończył 18 lat", ["Gdy jest cudzoziemcem", "Gdy jest bezrobotny", "Gdy grozi mu tylko grzywna"],
     "Art. 79 § 1 KPK: obrona jest obowiązkowa m.in., gdy oskarżony nie ukończył 18 lat, jest głuchy, niemy lub niewidomy albo zachodzą uzasadnione wątpliwości co do jego poczytalności."),
    ("Kiedy oskarżony musi mieć obrońcę w postępowaniu przed sądem okręgowym?",
     "Gdy zarzucono mu zbrodnię", ["W każdej sprawie przed tym sądem", "Gdy zarzucono mu występek", "Gdy jest tymczasowo aresztowany"],
     "Art. 80 KPK: oskarżony musi mieć obrońcę przed sądem okręgowym, jeżeli zarzucono mu zbrodnię; udział obrońcy w rozprawie głównej jest wtedy obowiązkowy."),
    ("Czy była żona oskarżonego może odmówić zeznań w jego sprawie?",
     "Tak, prawo trwa po rozwodzie", ["Nie, po rozwodzie traci to prawo", "Tylko za zgodą sądu", "Tylko co do faktów z czasu małżeństwa"],
     "Art. 182 § 1 i 2 KPK: osoba najbliższa może odmówić zeznań, a prawo to trwa mimo ustania małżeństwa lub przysposobienia."),
    ("W ciągu ilu godzin od zatrzymania zatrzymany musi zostać przekazany do dyspozycji sądu z wnioskiem o areszt, aby nie został zwolniony?",
     "48 godzin", ["24 godziny", "36 godzin", "12 godzin"],
     "Art. 248 § 1 KPK: zatrzymanego zwalnia się, jeżeli w ciągu 48 godzin od zatrzymania nie zostanie przekazany do dyspozycji sądu wraz z wnioskiem o tymczasowe aresztowanie."),
    ("Ile czasu ma sąd od przekazania mu zatrzymanego na doręczenie lub ogłoszenie postanowienia o tymczasowym aresztowaniu?",
     "24 godziny", ["48 godzin", "72 godziny", "12 godzin"],
     "Art. 248 § 2 KPK: zatrzymanego zwalnia się, jeżeli w ciągu 24 godzin od przekazania go do dyspozycji sądu nie doręczono mu postanowienia o tymczasowym aresztowaniu albo nie ogłoszono go na posiedzeniu zdalnym."),
    ("Która okoliczność jest ogólną przesłanką stosowania tymczasowego aresztowania?",
     "Uzasadniona obawa ucieczki", ["Wcześniejsza karalność oskarżonego", "Odmowa składania wyjaśnień", "Nieprzyznanie się do winy"],
     "Art. 258 § 1 pkt 1 KPK: środki zapobiegawcze można stosować m.in. przy uzasadnionej obawie ucieczki lub ukrycia się oskarżonego. Odmowa wyjaśnień jest prawem oskarżonego i nie uzasadnia aresztu."),
    ("Na jaki najdłuższy okres sąd stosuje tymczasowe aresztowanie w postępowaniu przygotowawczym, określając jego pierwszy termin?",
     "3 miesiące", ["6 miesięcy", "12 miesięcy", "4 miesiące"],
     "Art. 263 § 1 KPK: w postępowaniu przygotowawczym sąd oznacza termin aresztowania na okres nie dłuższy niż 3 miesiące. Przedłużenia nie mogą łącznie przekroczyć 12 miesięcy (§ 2)."),
    ("Kto jest stroną w postępowaniu przygotowawczym?",
     "Pokrzywdzony i podejrzany", ["Prokurator i podejrzany", "Policja i pokrzywdzony", "Pokrzywdzony i świadek"],
     "Art. 299 § 1 KPK: w postępowaniu przygotowawczym stronami są pokrzywdzony i podejrzany. Prokuratorowi przysługują prawa strony tylko w czynnościach sądowych (§ 3)."),
    ("Co określa się w postanowieniu o wszczęciu śledztwa?",
     "Czyn i jego kwalifikację prawną", ["Dane osobowe podejrzanego", "Listę świadków oskarżenia", "Wysokość grożącej kary"],
     "Art. 303 KPK: w postanowieniu o wszczęciu śledztwa określa się czyn będący przedmiotem postępowania oraz jego kwalifikację prawną; śledztwo toczy się wtedy w sprawie, nie przeciwko osobie."),
    ("W jakim terminie powinno być co do zasady ukończone dochodzenie?",
     "2 miesiące", ["4 miesiące", "3 miesiące", "6 miesięcy"],
     "Art. 325i § 1 KPK: dochodzenie powinno być ukończone w ciągu 2 miesięcy; prokurator może przedłużyć je do 3 miesięcy, a w szczególnie uzasadnionych wypadkach na dalszy czas."),
    ("Do jakiej wartości przedmiotu przestępstwa lub szkody prowadzi się dochodzenie w sprawach o przestępstwa przeciwko mieniu?",
     "200 000 zł", ["100 000 zł", "50 000 zł", "500 000 zł"],
     "Art. 325b § 1 pkt 1 KPK: przy przestępstwach przeciwko mieniu dochodzenie prowadzi się tylko, gdy wartość przedmiotu albo szkoda wyrządzona lub grożąca nie przekracza 200 000 zł."),
    ("Do kiedy oskarżony może złożyć wniosek o wydanie wyroku skazującego bez postępowania dowodowego?",
     "Do końca pierwszych przesłuchań", ["Do zamknięcia przewodu sądowego", "Do wydania wyroku w I instancji", "Do doręczenia aktu oskarżenia"],
     "Art. 387 § 1 KPK: wniosek można złożyć do chwili zakończenia pierwszego przesłuchania wszystkich oskarżonych na rozprawie głównej, jeśli czyn jest zagrożony karą nieprzekraczającą 15 lat."),
    ("Kiedy sąd odwoławczy może orzec na niekorzyść oskarżonego?",
     "Gdy wniesiono środek na jego niekorzyść", ["Zawsze, gdy uzna to za słuszne", "Gdy apelację wniósł tylko obrońca", "Gdy oskarżony nie stawił się"],
     "Art. 434 § 1 pkt 1 KPK: orzeczenie na niekorzyść oskarżonego jest możliwe tylko, gdy wniesiono środek odwoławczy na jego niekorzyść, i to w granicach zaskarżenia."),
    ("Ile wynosi termin do wniesienia apelacji w procesie karnym od doręczenia wyroku z uzasadnieniem?",
     "14 dni", ["7 dni", "10 dni", "30 dni"],
     "Art. 445 § 1 KPK: termin do wniesienia apelacji wynosi 14 dni i biegnie dla każdego uprawnionego od daty doręczenia mu wyroku z uzasadnieniem."),
    ("W jakim terminie strona wnosi kasację od doręczenia orzeczenia z uzasadnieniem?",
     "30 dni", ["45 dni", "60 dni", "90 dni"],
     "Art. 524 § 1 KPK: termin do wniesienia kasacji dla stron wynosi 30 dni od daty doręczenia orzeczenia z uzasadnieniem. Nie wiąże on Prokuratora Generalnego, RPO i RPD (§ 2)."),
    ("Czy prokurator może wnieść środek odwoławczy na korzyść oskarżonego?",
     "Tak, ma takie prawo", ["Nie, tylko na niekorzyść", "Tylko za zgodą oskarżonego", "Tylko w sprawach o zbrodnie"],
     "Art. 425 § 4 KPK: oskarżyciel publiczny ma prawo wnieść środek odwoławczy także na korzyść oskarżonego; nie dotyczy go też wymóg gravamen (§ 3)."),
    ("Kto wnosi i popiera oskarżenie o przestępstwa ścigane z oskarżenia prywatnego?",
     "Pokrzywdzony jako oskarżyciel prywatny", ["Prokurator na wniosek pokrzywdzonego", "Policja w trybie dochodzenia", "Rzecznik Praw Obywatelskich"],
     "Art. 59 § 1 KPK: pokrzywdzony może jako oskarżyciel prywatny wnosić i popierać oskarżenie o przestępstwa ścigane z oskarżenia prywatnego."),
    ("Od kiedy osobę uważa się za podejrzanego?",
     "Od przedstawienia jej zarzutów", ["Od złożenia na nią zawiadomienia", "Od wszczęcia śledztwa w sprawie", "Od wniesienia aktu oskarżenia"],
     "Art. 71 § 1 KPK: podejrzanym jest osoba, co do której wydano postanowienie o przedstawieniu zarzutów albo której postawiono zarzut przy przesłuchaniu. Po wniesieniu aktu oskarżenia jest oskarżonym (§ 2)."),
]
